fn words_of(s: Str) -> List[Str] {
    var out: List[Str] = []
    var cur = ""
    for c in s.chars() {
        if c == " " {
            if cur != "" {
                out = out.push(cur)
                cur = ""
            }
        } else {
            cur = cur + c
        }
    }
    if cur != "" {
        out = out.push(cur)
    }
    return out
}

fn str_at(xs: List[Str], i: Int) -> Str {
    match xs.get(i) {
        Some(v) => {
            return v
        }
        None => {
            return ""
        }
    }
}

fn find_index(xs: List[Str], k: Str) -> Int {
    var i = 0
    for x in xs {
        if x == k {
            return i
        }
        i = i + 1
    }
    return -1
}

fn remove_at(xs: List[Str], idx: Int) -> List[Str] {
    var out: List[Str] = []
    var i = 0
    for x in xs {
        if i != idx {
            out = out.push(x)
        }
        i = i + 1
    }
    return out
}

pub fn lru(capacity: Int, ops: List[Str]) -> List[Str] {
    var keys: List[Str] = []
    var vals: List[Str] = []
    var out: List[Str] = []
    for op in ops {
        let w = words_of(op)
        let cmd = str_at(w, 0)
        if cmd == "put" {
            let k = str_at(w, 1)
            let v = str_at(w, 2)
            let idx = find_index(keys, k)
            if idx >= 0 {
                keys = remove_at(keys, idx)
                vals = remove_at(vals, idx)
            } else {
                if keys.len() >= capacity and keys.len() > 0 {
                    keys = remove_at(keys, 0)
                    vals = remove_at(vals, 0)
                }
            }
            if capacity > 0 {
                keys = keys.push(k)
                vals = vals.push(v)
            }
        } else {
            let k = str_at(w, 1)
            let idx = find_index(keys, k)
            if idx < 0 {
                out = out.push("-")
            } else {
                let v = str_at(vals, idx)
                keys = remove_at(keys, idx)
                vals = remove_at(vals, idx)
                keys = keys.push(k)
                vals = vals.push(v)
                out = out.push(v)
            }
        }
    }
    return out
}
